// /shop/<section>/<key> — one static page per sticker (generated by tools/build-state-pages.mjs).
// The HTML already has the art, blurb, letters and sizes; this only adds the style/size switch and live price/cart.
import './main.js';
import { addToCart } from './cart.js';
import { escapeHtml, money } from './cart-ui.js';
import { parse, variantFor } from './catalog-parse.js';
import { sectionByKey } from './sections.js';
import { sizeLabel } from './size-label.js';

const main = document.getElementById('main');
const key = main?.dataset.key || '';
const section = sectionByKey(main?.dataset.section || 'states');
const sizesEl = document.getElementById('sp-sizes'); // radios, multi-size sections only
const seg = document.querySelector('.sp-toggle .seg');
const figs = [...document.querySelectorAll('.sp-fig')];
const priceEl = document.getElementById('sp-price');
const styleNameEl = document.getElementById('sp-style-name');
const addBtn = document.getElementById('sp-add');
const statusEl = document.getElementById('sp-status');

let byStyle = new Map(); // styleKey → parsed product for this page
let loaded = false; // finished trying /api/products
let selected = seg?.querySelector('[aria-checked="true"]')?.dataset.style || 'real-photo';

const checkedSize = () => sizesEl?.querySelector('input:checked') || null;

/** The Printful variant for the selected style (and size), if it's live. */
function chosen() {
  const it = byStyle.get(selected);
  if (!it) return { it: null, variant: null };
  const size = checkedSize();
  return { it, variant: size ? (it.vs.length ? variantFor(it, size.value) : null) : it.v };
}

/** Button + price for the selected style and size. The static price stays until a live price is in. */
function update() {
  const { it, variant } = chosen();
  const size = checkedSize();
  if (it && variant) {
    priceEl.textContent = money(variant.retail_price);
    addBtn.disabled = false;
    addBtn.innerHTML = `Add to cart<span class="sr-only"> — ${escapeHtml(`${it.title}, ${it.style}${size ? `, ${sizeLabel(variant.size)}` : ''}`)}</span>`;
  } else {
    if (size?.dataset.price) priceEl.textContent = `$${size.dataset.price}`;
    addBtn.disabled = true;
    addBtn.textContent = !loaded ? 'Loading…' : section?.comingSoon ? 'Coming soon' : 'Unavailable right now';
  }
  // Live prices on the size options once they're in.
  sizesEl?.querySelectorAll('input').forEach((input) => {
    const v = it ? variantFor(it, input.value) : null;
    const out = input.closest('label')?.querySelector('.sx-size-price');
    if (out) out.textContent = v && it.vs.length ? money(v.retail_price) : `$${input.dataset.price}`;
  });
}

sizesEl?.addEventListener('change', () => { statusEl.textContent = ''; update(); });

function select(style) {
  if (!style || style === selected) return;
  selected = style;
  seg.querySelectorAll('.seg-btn').forEach((b) => {
    const on = b.dataset.style === style;
    b.setAttribute('aria-checked', String(on));
    b.tabIndex = on ? 0 : -1;
  });
  figs.forEach((f) => f.classList.toggle('is-main', f.dataset.style === style));
  const btn = seg.querySelector(`[data-style="${CSS.escape(style)}"]`);
  if (styleNameEl && btn) styleNameEl.textContent = btn.textContent;
  statusEl.textContent = '';
  update();
}

seg?.addEventListener('click', (e) => {
  const b = e.target.closest('.seg-btn');
  if (b) select(b.dataset.style);
});
// Radio group arrows, like the popup's toggle.
seg?.addEventListener('keydown', (e) => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
  e.preventDefault();
  const btns = [...seg.querySelectorAll('.seg-btn')];
  const i = btns.findIndex((b) => b.dataset.style === selected) + (e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 1);
  const next = btns[(i + btns.length) % btns.length];
  select(next.dataset.style);
  next.focus();
});
// Clicking the smaller image also selects it.
figs.forEach((f) => f.addEventListener('click', () => select(f.dataset.style)));

let addedTimer;
addBtn?.addEventListener('click', () => {
  const { it, variant } = chosen();
  if (!it || !variant) return;
  const size = sizeLabel(variant.size);
  // Same item shape and name format as addItem() in shop.js.
  addToCart({
    sync_variant_id: variant.sync_variant_id,
    name: `${it.title} — ${it.style} · ${size}`.replace(/ · $/, ''),
    thumbnail: it.thumb || null,
    retail_price: variant.retail_price,
  });
  addBtn.classList.add('is-added');
  addBtn.firstChild.textContent = 'Added ✓';
  statusEl.innerHTML = `Added ${escapeHtml(`${it.title} ${it.style}${checkedSize() ? `, ${size}` : ''}`)} to cart. <a href="/shop#cart">View cart</a>`;
  clearTimeout(addedTimer);
  addedTimer = setTimeout(() => { addBtn.classList.remove('is-added'); addBtn.firstChild.textContent = 'Add to cart'; }, 1600);
});

async function load(attempt = 0) {
  try {
    const res = await fetch('/api/products', attempt ? { cache: 'no-store' } : undefined);
    const data = await res.json();
    const products = Array.isArray(data.products) ? data.products : [];
    byStyle = new Map(
      products
        .map(parse)
        .filter((it) => it.section === section && it.v && Number(it.v.retail_price) > 0 && it.key === key)
        .map((it) => [it.styleKey, it]),
    );
    // A large catalog fills in over a few requests (see shop.js); poll briefly until this state is in.
    if (data.partial && byStyle.size < figs.length && attempt < 5) {
      update();
      setTimeout(() => load(attempt + 1), 1500);
      return;
    }
  } catch {
    /* keep the static price; the button says unavailable */
  }
  loaded = true;
  update();
}

// ?style=<key>&size=<3x3> (the Offer URLs in the structured data) open with that style/size selected.
const q = new URLSearchParams(location.search);
const wanted = q.get('style');
if (wanted && figs.some((f) => f.dataset.style === wanted)) select(wanted);
const wantedSize = sizesEl?.querySelector(`input[value="${CSS.escape(q.get('size') || '')}"]`);
if (wantedSize) wantedSize.checked = true;

update();
load();
